mapper.select:
select o.* from orders o

    o.user_id = #{userId}

        and o.status = #{dto.status}


order by o.order_time desc, o.id desc

select o.* from orders o


        and o.status = #{dto.status}


        and o.order_time >= #{dto.beginTime}


        and o.order_time <= #{dto.endTime}


        and o.status = #{dto.number}


        and o.phone = #{dto.phone}


order by o.order_time desc, o.id desc

select od.name as name, sum(od.number) as number
from order_detail od,
     orders o
where od.order_id = o.id
  and o.status = 5
  and o.order_time >= #{beginTime}
  and o.order_time < #{endTime}
group by name
order by number desc limit 0, 10
